    /**
     * @method
     * @name mercado#fetchMarkets
     * @description retrieves data on all markets for mercado
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public CompletableFuture<Object> fetchMarkets(Object... optionalArgs)
    {

        return BaseExchange.supplyAsync(() -> {

            Object parameters = optionalArgs != null && optionalArgs.length > 0 ? optionalArgs[0] : new HashMap<String, Object>() {{}};
            List<Object> response = (this.publicGetCoins(parameters)).join();
            //
            //     [
            //         "BCH",
            //         "BTC",
            //         "ETH",
            //         "LTC",
            //         "XRP",
            //         "MBPRK01",
            //         "MBPRK02",
            //         "MBPRK03",
            //         "MBPRK04",
            //         "MBCONS01",
            //         "USDC",
            //         "WBX",
            //         "CHZ",
            //         "MBCONS02",
            //         "PAXG",
            //         "MBVASCO01",
            //         "LINK"
            //     ]
            //
            List<Object> result = new ArrayList<Object>(Arrays.asList());
            Map<String, Object> amountLimits = (Map<String, Object>) this.safeDict(this.options, "limits", new HashMap<String, Object>() {{}});
            List<Object> coins = this.toArray(response);
            for (var i = 0; i < ((List<?>)coins).size(); i++)
            {
                Object coin = (coins == null || i < 0 || i >= coins.size() ? null : coins.get(i));
                Object baseId = coin;
                String quoteId = "BRL";
                String base = this.safeCurrencyCode(baseId);
                String quote = this.safeCurrencyCode(quoteId);
                if ((java.util.Objects.equals(base, null)) || (java.util.Objects.equals(quote, null)))
                {
                    continue;
                }
                String id = (quote + base);
    final Object finalBase = base;
                final Object finalQuote = quote;
                            ((List<Object>)result).add(new HashMap<String, Object>() {{
                    put( "id", id );
                    put( "symbol", ((finalBase + "/") + finalQuote) );
                    put( "base", finalBase );
                    put( "quote", finalQuote );
                    put( "settle", null );
                    put( "baseId", baseId );
                    put( "quoteId", quoteId );
                    put( "settleId", null );
                    put( "type", "spot" );
                    put( "spot", true );
                    put( "margin", false );
                    put( "swap", false );
                    put( "future", false );
                    put( "option", false );
                    put( "active", null );
                    put( "contract", false );
                    put( "linear", null );
                    put( "inverse", null );
                    put( "contractSize", null );
                    put( "expiry", null );
                    put( "expiryDatetime", null );
                    put( "strike", null );
                    put( "optionType", null );
                    put( "precision", new HashMap<String, Object>() {{
                        put( "amount", Mercado.this.parseNumber("1e-8") );
                        put( "price", Mercado.this.parseNumber("1e-5") );
                    }} );
                    put( "limits", new HashMap<String, Object>() {{
                        put( "leverage", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new HashMap<String, Object>() {{
                            put( "min", Mercado.this.safeNumber(amountLimits, baseId) );
                            put( "max", null );
                        }} );
                        put( "price", new HashMap<String, Object>() {{
                            put( "min", Mercado.this.parseNumber("1e-5") );
                            put( "max", null );
                        }} );
                        put( "cost", new HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                    }} );
                    put( "created", null );
                    put( "info", coin );
                }});
            }
            return result;
        });

    }

